cmd:
DREDD_API_KEY=$(cat ~/.claude/dredd/api-key 2>/dev/null)
for n in 11 13 14 15; do
  url="https://bedt${n}.aisandbox.dev.ckotech.internal/status"
  echo "=== bedt${n} ==="
  curl -sk -H "Authorization: Bearer $DREDD_API_KEY" "$url" 2>/dev/null | python3 -c "
import sys, json
try:
    d = json.load(sys.stdin)
    s = d.get('status') or d.get('state','?')
    rid = d.get('runId','?')
    elapsed = d.get('elapsedSec') or d.get('elapsed_seconds') or 0
    print('status:', s)
    print('runId :', rid)
    if elapsed: print(f'elapsed: {elapsed}s ({elapsed//60}m)')
    # Check stats
    for k in ('completed','total','progress','reps','failed'):
        if k in d: print(f'  {k}: {d[k]}')
    if 'params' in d:
        p = d['params']
        for k in ('total_runs','TOTAL','reps','test'):
            if k in p: print(f'  param.{k}: {p[k]}')
except Exception as e:
    print('parse err:', e)
"
done
